/// setter for IN EventPort
pub fn put_pulse(value: Option<u8>)
{
  *extern_api::IN_pulse.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// setter for IN EventDataPort
pub fn put_sample(value: Option<i32>)
{
  *extern_api::IN_sample.lock().unwrap_or_else(|e| e.into_inner()) = value
}

/// setter for IN DataPort
pub fn put_level(value: i32)
{
  *extern_api::IN_level.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN EventDataPort
pub fn put_flag(value: Option<bool>)
{
  *extern_api::IN_flag.lock().unwrap_or_else(|e| e.into_inner()) = value
}

