/// getter for OUT EventPort
pub fn get_ack() -> Option<u8>
{
  return extern_api::OUT_ack.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

/// getter for OUT EventDataPort
pub fn get_echo() -> Option<i32>
{
  return extern_api::OUT_echo.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

/// getter for OUT EventDataPort
pub fn get_alert_result() -> Option<bool>
{
  return extern_api::OUT_alert_result.lock().unwrap_or_else(|e| e.into_inner()).clone()
}

/// getter for OUT DataPort
pub fn get_healthy() -> bool
{
  return extern_api::OUT_healthy.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_sprevious_level() -> i32
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.sprevious_level,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_sprevious_level(value: i32)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.sprevious_level = value,
      None => panic!("The app is None")
    }
  }
}
